  ('mission-w19-03', 'world-19', 'campaign-19a', 'operation-19a-1', 'who-goes-there', 'Who Goes There?', 'Authentication proves who you are. Authorization decides what you''re allowed to do once you''re in. Confusing the two is how privilege creeps.', 'beginner', ARRAY['luna'], '{"requiredMissionIds":["mission-w19-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"access-control-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 3),
